import React, { useState, useEffect } from 'react'
import { Container, Row, Col, Table, Button, Badge } from 'reactstrap'
import { BASE_URL } from '../../utils/config'

const ManageUsers = () => {
   const [users, setUsers] = useState([])
   const [loading, setLoading] = useState(true)
   const [error, setError] = useState(null)

   useEffect(() => {
      const fetchUsers = async () => {
         try {
            // LẤY TOKEN TỪ LOCALSTORAGE (BE yêu cầu để verifyAdmin)
            const token = localStorage.getItem('token') 

            const res = await fetch(`${BASE_URL}/users`, {
               method: 'GET',
               headers: {
                  // Gửi Token đi để Backend xác nhận bạn là Admin
                  'Authorization': `Bearer ${token}` 
               }
            })

            const result = await res.json()

            if (!res.ok) {
               // Nếu Backend trả về lỗi (401, 403...)
               setError(result.message || "Bạn không có quyền truy cập!")
            } else {
               // Bóc tách đúng trường 'data' mà Backend trả về
               setUsers(result.data || [])
            }
            setLoading(false)
         } catch (err) {
            setError("Lỗi kết nối đến Server!")
            setLoading(false)
         }
      }

      fetchUsers()
   }, [])

   const deleteUser = async (id) => {
      if (window.confirm("Bạn có chắc chắn muốn xóa người dùng này?")) {
         try {
            const token = localStorage.getItem('token')
            const res = await fetch(`${BASE_URL}/users/${id}`, {
               method: 'DELETE',
               headers: {
                  'Authorization': `Bearer ${token}`
               }
            })
            const result = await res.json()
            if (res.ok) {
               alert("Xóa thành công!")
               setUsers(prev => prev.filter(user => user._id !== id)) // Xóa trực tiếp trên giao diện cho nhanh
            } else {
               alert(result.message)
            }
         } catch (err) {
            alert("Lỗi máy chủ!")
         }
      }
   }

   return (
      <section className="mt-5 pt-5">
         <Container>
            <Row>
               <Col lg='12'>
                  <div className="d-flex align-items-center justify-content-between mb-4">
                     <h3 className="fw-bold">Danh sách thành viên</h3>
                     <Badge color="info" className="p-2">{users?.length} Người dùng</Badge>
                  </div>

                  {loading && <h4 className="text-center pt-5">Đang tải dữ liệu...</h4>}
                  {error && <h4 className="text-center pt-5 text-danger">{error}</h4>}

                  {!loading && !error && (
                     <Table hover responsive className="shadow-sm bg-white rounded">
                        <thead className="bg-light">
                           <tr>
                              <th>Tên người dùng</th>
                              <th>Email</th>
                              <th>Vai trò</th>
                              <th>Ngày tham gia</th>
                              <th className="text-center">Thao tác</th>
                           </tr>
                        </thead>
                        <tbody>
                           {users.length > 0 ? (
                              users.map(user => (
                                 <tr key={user._id}>
                                    <td className="fw-bold text-dark">{user.username}</td>
                                    <td>{user.email}</td>
                                    <td>
                                       <Badge color={user.role === 'admin' ? 'danger' : 'success'} pill>
                                          {user.role}
                                       </Badge>
                                    </td>
                                    <td>{new Date(user.createdAt).toLocaleDateString('vi-VN')}</td>
                                    <td className="text-center">
                                       <Button color="danger" size="sm" onClick={() => deleteUser(user._id)}>
                                          <i className="ri-delete-bin-line"></i>
                                       </Button>
                                    </td>
                                 </tr>
                              ))
                           ) : (
                              <tr>
                                 <td colSpan="5" className="text-center">Không có người dùng nào.</td>
                              </tr>
                           )}
                        </tbody>
                     </Table>
                  )}
               </Col>
            </Row>
         </Container>
      </section>
   )
}

export default ManageUsers
